-- Phase 26: vendors.settlement_model (SPEC core 5: every existing and new shop is Model B,
-- PLATFORM_ESCROW, until a model change is requested and approved) and home_promotions (the Home
-- banners and Featured Offers tiles, STATE_HANDOFF 8Z.4). Generated by drizzle-kit; the trigger at
-- the end is hand-added. Both enum types are created here (CREATE TYPE, not ADD VALUE), so their
-- values can be used in this same migration.
CREATE TYPE "public"."settlement_model" AS ENUM('COD_CREDIT', 'PLATFORM_ESCROW', 'DIRECT_PREPAID');--> statement-breakpoint
CREATE TYPE "public"."promotion_placement" AS ENUM('CAROUSEL', 'FEATURED');--> statement-breakpoint
CREATE TYPE "public"."promotion_target_type" AS ENUM('SHOP', 'CATEGORY', 'DISCOUNT_TAG');--> statement-breakpoint
CREATE TABLE "home_promotions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"placement" "promotion_placement" NOT NULL,
	"image_url" text,
	"title" text,
	"subtitle" text,
	"target_type" "promotion_target_type",
	"target_value" text,
	"display_order" integer DEFAULT 0 NOT NULL,
	"is_active" boolean DEFAULT true NOT NULL,
	"starts_at" timestamp with time zone,
	"ends_at" timestamp with time zone,
	"is_sponsored" boolean DEFAULT false NOT NULL,
	"ad_purchase_id" uuid,
	"created_by_user_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "home_promotions_display_order_check" CHECK ("home_promotions"."display_order" >= 0),
	CONSTRAINT "home_promotions_image_check" CHECK ("home_promotions"."placement" <> 'CAROUSEL' OR "home_promotions"."image_url" IS NOT NULL),
	CONSTRAINT "home_promotions_title_check" CHECK ("home_promotions"."placement" <> 'FEATURED' OR "home_promotions"."title" IS NOT NULL),
	CONSTRAINT "home_promotions_text_check" CHECK (("home_promotions"."title" IS NULL OR btrim("home_promotions"."title") <> '') AND ("home_promotions"."subtitle" IS NULL OR btrim("home_promotions"."subtitle") <> '')),
	CONSTRAINT "home_promotions_target_check" CHECK (("home_promotions"."target_type" IS NULL) = ("home_promotions"."target_value" IS NULL) AND ("home_promotions"."target_value" IS NULL OR btrim("home_promotions"."target_value") <> '')),
	CONSTRAINT "home_promotions_dates_check" CHECK ("home_promotions"."starts_at" IS NULL OR "home_promotions"."ends_at" IS NULL OR "home_promotions"."starts_at" < "home_promotions"."ends_at"),
	CONSTRAINT "home_promotions_sponsored_check" CHECK ("home_promotions"."is_sponsored" = ("home_promotions"."ad_purchase_id" IS NOT NULL)),
	CONSTRAINT "home_promotions_ad_purchase_pending_check" CHECK ("home_promotions"."ad_purchase_id" IS NULL)
);
--> statement-breakpoint
ALTER TABLE "vendors" ADD COLUMN "settlement_model" "settlement_model" DEFAULT 'PLATFORM_ESCROW' NOT NULL;--> statement-breakpoint
ALTER TABLE "home_promotions" ADD CONSTRAINT "home_promotions_created_by_user_id_users_id_fk" FOREIGN KEY ("created_by_user_id") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "home_promotions_listing_idx" ON "home_promotions" USING btree ("placement","is_active","display_order");--> statement-breakpoint
CREATE INDEX "home_promotions_created_by_user_id_idx" ON "home_promotions" USING btree ("created_by_user_id");--> statement-breakpoint

-- Hand-added.
CREATE TRIGGER home_promotions_set_updated_at BEFORE UPDATE ON home_promotions
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();
